mapper.sql:
WHERE 1=1
    AND (t.task_name LIKE CONCAT('%',#{keyword},'%') OR t.task_no LIKE CONCAT('%',#{keyword},'%') OR tr.run_no LIKE CONCAT('%',#{keyword},'%'))
    AND COALESCE(s.application,r.application)=#{application}
    AND COALESCE(s.version_no,r.version_no)=#{versionNo}

WHERE 1=1
    AND (i.title LIKE CONCAT('%',#{keyword},'%') OR i.file_path LIKE CONCAT('%',#{keyword},'%') OR t.task_no LIKE CONCAT('%',#{keyword},'%') OR t.task_name LIKE CONCAT('%',#{keyword},'%'))
    AND i.status=#{status}
    AND i.risk_level=#{risk}
    AND i.result_id=#{resultId}
    AND COALESCE(snap.application,cur.application,r.application)=#{application}
    AND COALESCE(snap.version_no,cur.version_no,r.version_no)=#{versionNo}
